export function AppSidebar({ ...props }: React.ComponentProps<typeof Sidebar>) {
  return (
    <Sidebar {...props}>
      <SidebarHeader className="flex flex-col gap-2">
        <VersionSwitcher
          versions={data.versions}
          defaultVersion={data.versions[0]}
        />
        <SearchForm />
      </SidebarHeader>
      <SidebarContent>
        {data.navMain.map((section) => (
          <SidebarSection key={section.title} label={section.title}>
            {section.items.map((link) => (
              <SidebarItem key={link.title} isCurrent={!!link.isActive}>
                <SidebarLink href={link.url}>{link.title}</SidebarLink>
              </SidebarItem>
            ))}
          </SidebarSection>
        ))}
      </SidebarContent>
      <SidebarRail />
    </Sidebar>
  )
}

import { SearchField } from "@/registry/preskok/ui/preskok-ui/search-field"

export function SearchForm({ ...props }: React.ComponentProps<"form">) {
  return (
    <form {...props}>
      <SearchField id="search" placeholder="Search the docs..." />
    </form>
  )
}

"use client"

import * as React from "react"
import { Check, ChevronsUpDown, GalleryVerticalEnd } from "lucide-react"

import {
  Menu,
  MenuContent,
  MenuItem,
  MenuTrigger,
} from "@/registry/preskok/ui/preskok-ui/menu"

export function VersionSwitcher({
  versions,
  defaultVersion,
}: {
  versions: Array<string>
  defaultVersion: string
}) {
  const [selectedVersion, setSelectedVersion] = React.useState(defaultVersion)

  return (
    <Menu>
      <MenuTrigger className="hover:bg-sidebar-accent hover:text-sidebar-accent-foreground flex w-full items-center gap-2 rounded-lg p-2 text-left">
        <div className="bg-sidebar-primary text-sidebar-primary-foreground flex aspect-square size-8 items-center justify-center rounded-lg">
          <GalleryVerticalEnd className="size-4" />
        </div>
        <div className="flex flex-col gap-0.5 text-sm leading-none">
          <span className="font-medium">Documentation</span>
          <span>v{selectedVersion}</span>
        </div>
        <ChevronsUpDown className="ml-auto" />
      </MenuTrigger>
      <MenuContent>
        {versions.map((version) => (
          <MenuItem
            key={version}
            onAction={() => {
              setSelectedVersion(version)
            }}
          >
            v{version}{" "}
            {version === selectedVersion && <Check className="ml-auto" />}
          </MenuItem>
        ))}
      </MenuContent>
    </Menu>
  )
}
